<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const livesEl = document.getElementById('lives');
  const bestEl  = document.getElementById('best');
  const overlay = document.getElementById('overlay');
  const ovTitle = document.getElementById('ov-title');
  const ovMsg   = document.getElementById('ov-msg');
  const ovScore = document.getElementById('ov-score');
  const ovBtn   = document.getElementById('ov-btn');

  // ---------- 状態 ----------
  let state = 'idle'; // idle | playing | paused | over | clear
  let score = 0, level = 1, lives = 3;
  let best = Number(localStorage.getItem('breakout_best') || 0);
  bestEl.textContent = best;

  const paddle = { w: 96, h: 12, x: W/2 - 48, y: H - 30, speed: 520 };
  const ball   = { x: W/2, y: H/2, r: 7, vx: 0, vy: 0, speed: 320 };
  let blocks = [];
  let particles = [];
  let keys = {};

  const ROW_COLORS = ['#ff5d5d','#ff9a3d','#ffe14d','#5dff8a','#5db8ff','#b07dff'];

  function buildLevel() {
    const cols = 10;
    const rows = Math.min(4 + level, 8);
    const gap = 6;
    const bw = (W - 40 - gap * (cols - 1)) / cols;
    const bh = 22;
    blocks = [];
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        // 上位の行ほど硬い(HP2)
        const hp = r < 2 && level >= 2 ? 2 : 1;
        blocks.push({
          x: 20 + c * (bw + gap),
          y: 50 + r * (bh + gap),
          w: bw, h: bh,
          color: ROW_COLORS[r % ROW_COLORS.length],
          hp, maxHp: hp,
          points: (rows - r) * 10
        });
      }
    }
  }

  function resetBall() {
    ball.x = paddle.x + paddle.w / 2;
    ball.y = paddle.y - ball.r - 1;
    const angle = (-Math.PI/2) + (Math.random() * 0.6 - 0.3);
    ball.speed = 300 + level * 30;
    ball.vx = Math.cos(angle) * ball.speed;
    ball.vy = Math.sin(angle) * ball.speed;
  }

  // ---------- 効果音(WebAudio) ----------
  let actx = null;
  function beep(freq, dur = 0.06, type = 'square', vol = 0.15) {
    try {
      actx = actx || new (window.AudioContext || window.webkitAudioContext)();
      const o = actx.createOscillator();
      const g = actx.createGain();
      o.type = type; o.frequency.value = freq;
      g.gain.setValueAtTime(vol, actx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, actx.currentTime + dur);
      o.connect(g); g.connect(actx.destination);
      o.start(); o.stop(actx.currentTime + dur);
    } catch (e) { /* 音が出なくても無視 */ }
  }
"}
